import {ACTIVE_MOTIONS,DEFAULT_CRITERIA,activeMotions,validateCriteria} from './v5-core.mjs';
import {calibrateIRER,irerAuxiliary} from './motion-metrics.mjs';
import {externalRotation} from './v5-core.mjs';
import {templateStore,validateCapture,postureFeatures} from './neutral.mjs';
import {setupAdminTabs} from './admin-tabs.mjs?v=5.2.0-admin3';

export function validateSettingsBackup(v){
 if(v?.schema!=='shoulder-settings-1'||!Array.isArray(v.templates))throw Error('설정 백업 형식 오류');
 validateCriteria(v.criteria);if(v.capture)validateCapture(v.capture);
 const ids=new Set();for(const t of v.templates){
  if(typeof t.id!=='string'||!t.id||ids.has(t.id)||!ACTIVE_MOTIONS.includes(t.motion)||!['left','right'].includes(t.arm)||!['정면','측면','후면'].includes(t.view)||!/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(t.image)||!postureFeatures(t.corrected,t.arm)||!t.features||!['shoulder','elbow','wristX','wristY'].every(k=>Number.isFinite(t.features[k]))||!(t.angleTolerance>0&&t.angleTolerance<=60&&t.positionTolerance>0&&t.positionTolerance<=1))throw Error('자세 기준 데이터 오류');ids.add(t.id);
 }
 if(v.selected&&Object.values(v.selected).some(id=>id&&!ids.has(id)))throw Error('선택 기준 버전이 백업에 없습니다.');
 return v;
}

export function setupFullV52(api){
 const {state,session,patient,camera,queue,selectMotion,renderAll,showToast,recalculateCurrentRom,selectFrame,renderWorkflow}=api,$=s=>document.querySelector(s);
 const defaults={arm:'right',frameStep:3,facing:'right',irer:{maxDifference:15,scaleTolerance:.25}};
 function validateDefaults(v){if(!['left','right'].includes(v.arm)||!['left','right'].includes(v.facing)||!Number.isInteger(v.frameStep)||v.frameStep<1||v.frameStep>30||![v.irer?.maxDifference,v.irer?.scaleTolerance].every(Number.isFinite)||v.irer.maxDifference<=0||v.irer.maxDifference>90||v.irer.scaleTolerance<=0||v.irer.scaleTolerance>1)throw Error('기본 팔·간격·촬영 방향·IRER 허용값을 확인하세요.');return v;}
 try{state.defaults=validateDefaults(JSON.parse(localStorage.getItem('shoulder:v52:defaults')));}catch{state.defaults=structuredClone(defaults);}
 $('#v5-settings').insertAdjacentHTML('afterbegin',`<section class="v52-block"><h3>측정 동작 · 기본값</h3><p>FE2는 FE·ER의 통합 동작입니다. 함께 활성화하면 중복 평가될 수 있습니다. 활성 동작 가중치 합계는 100이어야 합니다.</p><div id="full-motions" class="v52-fields"></div><div class="v52-fields"><label>기본 측정 팔<select id="full-arm"><option value="right">오른팔</option><option value="left">왼팔</option></select></label><label>기본 분석 간격<input id="full-step" type="number" min="1" max="30"></label><label>FE2 몸 앞쪽 방향 (원본 영상)<select id="full-facing"><option value="right">화면 오른쪽</option><option value="left">화면 왼쪽</option></select></label><label>BIR 분할 수 (t0~tN)<input id="full-bir" type="number" min="1" max="100"></label><label>IRER 추정값 차이 허용 (°)<input id="full-difference" type="number" min="1" max="90"></label><label>IRER 거리 변화 허용 (비율)<input id="full-scale" type="number" min=".01" max="1" step=".01"></label></div><div class="v5-actions"><button id="full-equal" class="button ghost">활성 동작 균등 가중치</button><button id="full-save" class="button primary">기본값·동작 설정 저장</button><button id="full-reapply" class="button ghost">현재 검사에 최신 기준 적용·재계산</button><button id="full-reset" class="button ghost">전체 시험 기본값 복원</button><button id="full-export" class="button ghost">설정·자세기준 JSON 백업</button><label class="button ghost">설정 JSON 복원<input id="full-import" type="file" accept=".json" hidden></label></div><p id="full-status" role="status"></p></section>`);
 for(const k of ACTIVE_MOTIONS){const label=document.createElement('label'),check=document.createElement('input'),weight=document.createElement('input');check.type='checkbox';check.dataset.motion=k;weight.type='number';weight.min=0;weight.step='.01';weight.dataset.weight=k;weight.setAttribute('aria-label',k+' 활성 가중치');label.append(check,document.createTextNode(k),weight);$('#full-motions').append(label);}
 function fields(){for(const input of $('#full-motions').querySelectorAll('[data-motion]'))input.checked=activeMotions(state.criteria).includes(input.dataset.motion);for(const input of $('#full-motions').querySelectorAll('[data-weight]'))input.value=state.criteria.weights[input.dataset.weight]??0;$('#full-bir').value=state.criteria.birDivisions??10;$('#full-arm').value=state.defaults.arm;$('#full-step').value=state.defaults.frameStep;$('#full-facing').value=state.defaults.facing;$('#full-difference').value=state.defaults.irer.maxDifference;$('#full-scale').value=state.defaults.irer.scaleTolerance;}
 const hasData=()=>ACTIVE_MOTIONS.some(k=>state.sessions[k]?.fileName);
 function unifiedRows(){
  for(const row of $('#v5-criteria-rows').children){const code=row.querySelector('th').textContent;
   let check=row.querySelector('[data-enabled]');if(!check){const cell=document.createElement('td');cell.className='motion-enable-cell';check=document.createElement('input');check.type='checkbox';check.dataset.enabled=code;check.setAttribute('aria-label',code+' 사용');cell.append(check);row.prepend(cell);}
   check.checked=activeMotions(state.criteria).includes(code);row.classList.toggle('motion-disabled',!check.checked);check.onchange=()=>{$('#full-motions [data-motion="'+code+'"]').checked=check.checked;row.classList.toggle('motion-disabled',!check.checked);};
   const weight=row.querySelector('[data-field="weight"]');weight.value=$('#full-motions [data-weight="'+code+'"]').value;weight.oninput=()=>{$('#full-motions [data-weight="'+code+'"]').value=weight.value;};
   for(const input of row.querySelectorAll('[data-field^="t"]')){input.value=state.criteria.thresholds[code][Number(input.dataset.field[1])];delete input.dataset.edited;input.oninput=()=>input.dataset.edited='true';}
  }
  const header=$('#v5-criteria-rows').closest('table').querySelector('thead tr');if(header.children.length===5){const cell=document.createElement('th');cell.textContent='사용';cell.className='motion-enable-cell';header.prepend(cell);}
 }
 document.addEventListener('v52-rows-ready',unifiedRows);
 $('#full-equal').addEventListener('click',()=>{for(const input of $('#v5-criteria-rows').querySelectorAll('[data-field="weight"]'))input.value=$('#full-motions [data-weight="'+input.dataset.code+'"]').value;});
 function ensureIdle(){if(queue.running||state.cameraBusy||state.refining||state.view==='detail')throw Error('촬영·분석·상세 수정 완료 후 설정하세요.');}
 const notify=()=>document.dispatchEvent(new window.Event('v52-settings-changed'));
 function save(c,d,apply=false){ensureIdle();validateCriteria(c);validateDefaults(d);localStorage.setItem('shoulder:v5:criteria',JSON.stringify(c));localStorage.setItem('shoulder:v52:defaults',JSON.stringify(d));state.defaults=d;
  for(const item of Object.values(state.sessions)){item.frameStep=d.frameStep;if(apply)item.facing=d.facing;}
  $('#frame-step').value=d.frameStep;
  if(!hasData()||apply){if(apply&&hasData()){state.criteriaHistory??=[];state.criteriaHistory.push({at:new Date().toISOString(),criteria:structuredClone(state.criteria),results:Object.fromEntries(ACTIVE_MOTIONS.map(k=>[k,structuredClone(state.sessions[k].rom)]))});}state.criteria=c;if(apply)for(const k of ACTIVE_MOTIONS){const item=state.sessions[k];item.measurementSettings={birMode:c.birMode,birDivisions:c.birDivisions};item.irerOptions=structuredClone(d.irer);item.measurementConfirmed=false;}
   notify();if(!activeMotions(c).includes(state.activeMotion))selectMotion(activeMotions(c)[0]);renderWorkflow();}
  $('#full-status').textContent=hasData()&&!apply?'기본값 저장됨 · 현재 검사 기준은 유지됩니다. 새 검사부터 적용하거나 재계산을 선택하세요.':'기본값 저장·적용 완료 · 임상 미검증 시험 기준';
 }
 function read(){const c=structuredClone(state.criteria),d=validateDefaults({arm:$('#full-arm').value,frameStep:Number($('#full-step').value),facing:$('#full-facing').value,irer:{maxDifference:Number($('#full-difference').value),scaleTolerance:Number($('#full-scale').value)}});c.activeMotions=[...$('#full-motions').querySelectorAll('[data-motion]:checked')].map(x=>x.dataset.motion);for(const input of $('#full-motions').querySelectorAll('[data-weight]')){if(input.value==='')throw Error('가중치를 입력하세요.');c.weights[input.dataset.weight]=Number(input.value);}c.thresholds={...structuredClone(DEFAULT_CRITERIA.thresholds),...c.thresholds};for(const input of $('#v5-criteria-rows').querySelectorAll('[data-field^="t"]')){if(!input.value.trim())throw Error('점수 경계를 입력하세요.');c.thresholds[input.dataset.code][Number(input.dataset.field[1])]=Number(input.value);}const n=Number($('#full-bir').value),old=c.birDivisions??10;if(!$('#v5-criteria-rows').querySelector('[data-code="BIR"][data-edited]'))c.thresholds.BIR=(c.birMode==='relative-t'?c.thresholds.BIR:DEFAULT_CRITERIA.thresholds.BIR).map(v=>v*n/old);c.birDivisions=n;c.birMode='relative-t';c.version='pc-full-'+new Date().toISOString();return {c:validateCriteria(c),d};}
 $('#full-save').onclick=()=>{try{const {c,d}=read();save(c,d,true);const prior=state.activeMotion;for(const k of activeMotions(c)){selectMotion(k);recalculateCurrentRom();}selectMotion(prior);renderAll();unifiedRows();$('#full-status').textContent='설정 저장·현재 검사 적용 완료. 분석 간격 변경은 다음 분석·재분석부터 적용됩니다. 저장된 과거 검사는 유지됩니다.';}catch(e){$('#full-status').textContent=e.message;}};
 $('#full-equal').onclick=()=>{const codes=[...$('#full-motions').querySelectorAll('[data-motion]:checked')].map(x=>x.dataset.motion);for(const input of $('#full-motions').querySelectorAll('[data-weight]'))input.value=codes.includes(input.dataset.weight)?(codes.indexOf(input.dataset.weight)===codes.length-1?100-Math.floor(10000/codes.length)/100*(codes.length-1):Math.floor(10000/codes.length)/100):0;};
 $('#full-reset').onclick=()=>{try{save(structuredClone(DEFAULT_CRITERIA),structuredClone(defaults),true);fields();unifiedRows();renderAll();}catch(e){showToast(e.message);}};
 $('#full-reapply').onclick=()=>{try{const c=validateCriteria(JSON.parse(localStorage.getItem('shoulder:v5:criteria'))||structuredClone(DEFAULT_CRITERIA));save(c,state.defaults,true);const prior=state.activeMotion;for(const k of activeMotions(c)){selectMotion(k);recalculateCurrentRom();}selectMotion(prior);renderAll();showToast('최신 기준으로 재계산했습니다. 저장하면 검사에 반영됩니다.');}catch(e){showToast(e.message);}};
 function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 $('#full-export').onclick=async()=>{try{download('shoulder-v52-settings.json',{schema:'shoulder-settings-1',criteria:JSON.parse(localStorage.getItem('shoulder:v5:criteria'))??state.criteria,defaults:state.defaults,capture:JSON.parse(localStorage.getItem('shoulder:v52:capture')||'null'),camera:JSON.parse(localStorage.getItem('shoulder:camera')||'null'),selected:JSON.parse(localStorage.getItem('shoulder:v52:neutral-selection')||'{}'),templates:await templateStore('list')});}catch(e){showToast(e.message);}};
 $('#full-import').onchange=async e=>{try{
  const file=e.target.files?.[0];if(!file)return;if(file.size>30*1024*1024)throw Error('설정 백업은 30MB 이하로 선택하세요.');
  const v=validateSettingsBackup(JSON.parse(await file.text()));validateDefaults(v.defaults);ensureIdle();const existing=await templateStore('list');
  for(const t of v.templates){const same=existing.find(x=>x.id===t.id);if(same&&JSON.stringify(same)!==JSON.stringify(t))throw Error('같은 기준 ID에 다른 내용이 있습니다. 기존 기준은 보존됩니다.');}
  for(const t of v.templates)if(!existing.some(x=>x.id===t.id))await templateStore('save',t);
  save(v.criteria,v.defaults);if(v.capture)localStorage.setItem('shoulder:v52:capture',JSON.stringify(v.capture));if(v.camera)localStorage.setItem('shoulder:camera',JSON.stringify(v.camera));localStorage.setItem('shoulder:v52:neutral-selection',JSON.stringify(v.selected??{}));fields();showToast('복원 완료 · 카메라/자세 기준은 새로고침 후 적용됩니다.');
 }catch(error){showToast(error.message);}finally{e.target.value='';}};
 $('.correction-card .panel-actions').insertAdjacentHTML('beforebegin',`<section id="full-detail" class="v52-block"><div id="full-fe2" hidden><h3>FE2 양 극점</h3><label>몸 앞쪽 방향<select id="detail-facing"><option value="right">화면 오른쪽</option><option value="left">화면 왼쪽</option></select></label><div class="v5-actions"><button id="fe2-ext" class="button ghost">현재를 최대 신전으로</button><button id="fe2-flex" class="button ghost">현재를 최대 굴곡으로</button><button id="fe2-ext-go" class="button ghost">신전 프레임 보기</button><button id="fe2-flex-go" class="button ghost">굴곡 프레임 보기</button><button id="fe2-reset" class="button ghost">극점 자동값 복원</button></div><p id="fe2-info"></p></div><div id="full-irer" hidden><h3>IRER 개인 길이 보정</h3><p>전완이 영상면과 평행한 프레임을 선택하세요. 반대팔은 곧게 내립니다. 손목을 기본으로 사용합니다. 주먹 끝 사용 시 손끝 관절점을 주먹 끝 위치로 직접 수정하세요.</p><label>보정 기준<select id="irer-reference"><option value="wrist">손목</option><option value="fist">주먹 끝 (수동 지정)</option></select></label><button id="irer-calibrate" class="button ghost">현재 프레임으로 개인 길이 보정</button><button id="irer-clear" class="button ghost">개인 보정 해제</button><p id="irer-info"></p></div></section>`);
 function edited(message){const item=session();item.editHistory??=[];item.editHistory.push({at:new Date().toISOString(),action:message,sourceFrame:item.frames[state.currentIndex]?.sourceFrame});item.measurementConfirmed=false;recalculateCurrentRom();renderAll();}
 $('#detail-facing').onchange=()=>{session().facing=$('#detail-facing').value;session().fe2ExtensionFrame=null;session().fe2FlexionFrame=null;edited('FE2 방향 변경');};
 $('#fe2-ext').onclick=()=>{session().fe2ExtensionFrame=state.currentIndex;edited('FE2 신전 극점 선택');};$('#fe2-flex').onclick=()=>{session().fe2FlexionFrame=state.currentIndex;edited('FE2 굴곡 극점 선택');};
 $('#fe2-reset').onclick=()=>{session().fe2ExtensionFrame=null;session().fe2FlexionFrame=null;edited('FE2 자동 극점 복원');};
 $('#fe2-ext-go').onclick=()=>selectFrame(session().rom?.extensionFrameIndex??0);$('#fe2-flex-go').onclick=()=>selectFrame(session().rom?.flexionFrameIndex??0);
 $('#irer-calibrate').onclick=()=>{try{const item=session(),frame=item.frames[state.currentIndex];if(!frame)throw Error('분석 프레임을 선택하세요.');if($('#irer-reference').value==='fist'&&frame.corrected[patient().arm+'_hand_tip']?.status!=='manual')throw Error('주먹 끝 관절점을 수동으로 지정하세요.');item.irerCalibration={...calibrateIRER(frame.corrected,item.measuredArm||patient().arm,$('#irer-reference').value),sourceFrame:frame.sourceFrame,time:frame.time};item.irerOptions=structuredClone(state.defaults.irer);edited('IRER 개인 길이 보정');}catch(e){showToast(e.message);}};
 $('#irer-clear').onclick=()=>{session().irerCalibration=null;edited('IRER 보정 해제');};
 function render(){const active=activeMotions(state.criteria);for(const card of document.querySelectorAll('.motion-card'))card.hidden=!active.includes(card.dataset.motion);$('#v5-home p').textContent=`한쪽 팔 · ${active.length}개 동작 · 동작당 1회 후 재촬영 가능`;
  $('#full-detail').hidden=state.view!=='detail'||!['FE2','IRER'].includes(state.activeMotion);$('#full-fe2').hidden=state.activeMotion!=='FE2';$('#full-irer').hidden=state.activeMotion!=='IRER';const item=session(),r=item.rom;
  $('#detail-facing').value=item.facing??state.defaults.facing;
  if(state.activeMotion==='FE2')$('#fe2-info').textContent=`신전 ${r?.minAngle?.toFixed(1)??'—'}° → 굴곡 ${r?.maxAngle?.toFixed(1)??'—'}° · 전체 ${r?.rom?.toFixed(1)??'—'}°`;
  if(state.activeMotion==='IRER'){const f=item.frames[state.currentIndex],world=f?externalRotation(f.worldCorrected??f.worldRaw,patient().arm):null,aux=irerAuxiliary(f?.corrected,patient().arm,item.irerCalibration,world,item.irerOptions??state.defaults.irer);$('#irer-info').textContent=`3D ${world?.toFixed(1)??'—'}° / 길이 보조 ${aux.angle?.toFixed(1)??'—'}° / 차이 ${aux.difference?.toFixed(1)??'—'}° · ${aux.warnings.join(' / ')||'비교 가능'} · 추정점은 원본 관절점을 덮어쓰지 않습니다.`;}
  if(state.activeMotion==='BIR'&&state.criteria.birMode==='relative-t'){$('#bir-level').closest('label').hidden=true;$('#detail-a-label').textContent='손목 최대 도달 높이';$('#summary-max-label').textContent='손목 최대 도달 높이';$('#detail-a-meta').textContent='골반 t0 · 어깨 t'+(r?.divisions??state.criteria.birDivisions)+' · 손목 기준';}
 }
 function newExam(){state.examId=crypto.randomUUID();state.examCreatedAt=new Date().toISOString();state.criteriaHistory=[];try{state.criteria=validateCriteria(JSON.parse(localStorage.getItem('shoulder:v5:criteria'))??structuredClone(DEFAULT_CRITERIA));}catch{state.criteria=structuredClone(DEFAULT_CRITERIA);}const radio=$(`input[name="arm"][value="${state.defaults.arm}"]`);radio.checked=true;$('#frame-step').value=state.defaults.frameStep;notify();renderWorkflow();selectMotion(activeMotions(state.criteria)[0]);}
 $('#new-patient').addEventListener('click',()=>{if(!hasData())newExam();});
 if(!hasData()){$(`input[name="arm"][value="${state.defaults.arm}"]`).checked=true;$('#frame-step').value=state.defaults.frameStep;}
 document.addEventListener('v5-render',render);document.addEventListener('v52-criteria',fields);
 const settings=$('#v5-settings');settings.prepend(settings.querySelector('h2'));settings.prepend($('#v52-admin-close'));
 const grid=$('.motion-grid');for(const code of ACTIVE_MOTIONS){const card=grid.querySelector(`[data-motion="${code}"]`);if(card)grid.append(card);}
 fields();render();
 setupAdminTabs(settings);
 unifiedRows();
}
